"""Multiple Harvest

A farmer records the number of apples picked each day.
He notices that some consecutive days have a total that is a multiple of k.
He wants to know how many such stretches exist.
Given the daily counts `apples` (array of non-negative integers) and `k` (positive integer), return the number of contiguous subarrays whose sum is divisible by k.
"""
import unittest
import collections


def multipleHarvest(apples, k):
    """Return the number of contiguous subarrays whose sum is divisible by k.

    Track how many times we've encountered any given (mod) prefix-sum.
    Any time we see a repeat, that indicates a valid sequence from each of those previous starts.
    """
    prior_seen = collections.defaultdict(int)
    prior_seen[0] = 1
    count = 0
    cumsum = 0
    for i in apples:
        cumsum += i
        cumsum %= k
        count += prior_seen[cumsum]
        prior_seen[cumsum] += 1
    return count

    

























class TestSolution(unittest.TestCase):
    def test_data(self):
        self.assertEqual(multipleHarvest([4, 5, 0, 3, 2, 1], 5), 7)
        self.assertEqual(multipleHarvest([5, 10, 15], 5), 6)
        self.assertEqual(multipleHarvest([1, 2, 3], 7), 0)
        self.assertEqual(multipleHarvest([6], 3), 1)
        self.assertEqual(multipleHarvest([0, 0, 0], 2), 6)
